package android.animation;
import android.view.*;
import java.util.*;
/** Host-frame default layout transitions. Custom animator templates are not implemented. */
public class LayoutTransition {
 public static final int CHANGE_APPEARING=0,CHANGE_DISAPPEARING=1,APPEARING=2,DISAPPEARING=3,CHANGING=4;
 public interface TransitionListener {void startTransition(LayoutTransition transition,ViewGroup container,View view,int type);void endTransition(LayoutTransition transition,ViewGroup container,View view,int type);}
 private final boolean[] enabled={true,true,true,true,false};
 private final long[] duration={300,300,300,300,300},delay={0,300,300,0,0},stagger=new long[5];
 private final TimeInterpolator[] interpolators={new android.view.animation.DecelerateInterpolator(),new android.view.animation.DecelerateInterpolator(),new android.view.animation.AccelerateDecelerateInterpolator(),new android.view.animation.AccelerateDecelerateInterpolator(),new android.view.animation.DecelerateInterpolator()};
 private final ArrayList<TransitionListener> listeners=new ArrayList<TransitionListener>();
 private final ArrayList<Run> runs=new ArrayList<Run>();
 private final IdentityHashMap<View,View.OnLayoutChangeListener> pending=new IdentityHashMap<View,View.OnLayoutChangeListener>();
 private ViewGroup owner;private ViewTreeObserver observer;private ViewTreeObserver.OnPreDrawListener cleanup;private boolean parents=true,canceling;
 private final class Run {View view;ViewGroup parent;int type;ValueAnimator animator;Runnable finish;boolean notified,finished;}
 private static void type(int t){if(t<0||t>4)throw new IllegalArgumentException("Transition type");}
 private static void time(long value){if(value<0||value>86400000)throw new IllegalArgumentException("Transition time must be in [0,86400000] ms");}
 public void setDuration(long value){time(value);Arrays.fill(duration,value);}public void setDuration(int t,long value){type(t);time(value);duration[t]=value;}public long getDuration(int t){type(t);return duration[t];}
 public void setStartDelay(int t,long value){type(t);time(value);delay[t]=value;}public long getStartDelay(int t){type(t);return delay[t];}
 public void setStagger(int t,long value){type(t);time(value);stagger[t]=value;}public long getStagger(int t){type(t);return stagger[t];}
 public void setInterpolator(int t,TimeInterpolator value){type(t);interpolators[t]=value;}public TimeInterpolator getInterpolator(int t){type(t);return interpolators[t];}
 public void enableTransitionType(int t){type(t);enabled[t]=true;}public void disableTransitionType(int t){type(t);enabled[t]=false;}public boolean isTransitionTypeEnabled(int t){type(t);return enabled[t];}
 public void setAnimateParentHierarchy(boolean value){parents=value;}
 public void setAnimator(int t,Animator animator){type(t);if(animator!=null)throw new UnsupportedOperationException("Custom layout animator templates are not implemented");enabled[t]=false;}
 public Animator getAnimator(int t){type(t);throw new UnsupportedOperationException("Layout animator templates are not exposed");}
 public void addTransitionListener(TransitionListener listener){if(listener==null)throw new NullPointerException("listener");if(listeners.size()>=1024)throw new IllegalStateException("Transition listener limit");listeners.add(listener);}public void removeTransitionListener(TransitionListener listener){listeners.remove(listener);}public List<TransitionListener> getTransitionListeners(){return new ArrayList<TransitionListener>(listeners);}
 public boolean isRunning(){return !runs.isEmpty()||!pending.isEmpty();}public boolean isChangingLayout(){if(!pending.isEmpty())return true;for(Run run:runs)if(run.type==0||run.type==1||run.type==4)return true;return false;}
 public void shirazBind(ViewGroup parent){if(owner!=null&&parent!=null&&owner!=parent)throw new IllegalStateException("LayoutTransition already has an owner");owner=parent;}
 private boolean ready(ViewGroup parent){return !canceling&&parent.isAttachedToWindow()&&parent.isLaidOut()&&parent.isShown();}
 private void event(Run run,boolean start){for(TransitionListener listener:new ArrayList<TransitionListener>(listeners)){if(start)listener.startTransition(this,run.parent,run.view,run.type);else listener.endTransition(this,run.parent,run.view,run.type);if(start&&run.finished)break;}}
 private void finish(Run run){if(run.finished)return;run.finished=true;runs.remove(run);try{run.finish.run();}finally{if(run.notified)event(run,false);}}
 private void launch(final Run run,long extra){if(runs.size()>=4096)throw new IllegalStateException("Transition run limit");run.animator.setDuration(duration[run.type]);run.animator.setStartDelay(Math.min(86400000,delay[run.type]+extra));run.animator.setInterpolator(interpolators[run.type]);run.animator.addListener(new AnimatorListenerAdapter(){public void onAnimationEnd(Animator a){finish(run);}});runs.add(run);try{run.notified=true;event(run,true);if(!run.finished)run.animator.start();}catch(RuntimeException|Error error){try{finish(run);}catch(RuntimeException|Error cleanup){if(cleanup!=error)error.addSuppressed(cleanup);}throw error;}}
 private void cancelView(View view){for(Run run:new ArrayList<Run>(runs))if(run.view==view){try{if(run.animator.isStarted())run.animator.cancel();}finally{finish(run);}}View.OnLayoutChangeListener old=pending.remove(view);if(old!=null)view.removeOnLayoutChangeListener(old);}
 private static int[] bounds(View v){return new int[]{v.getLeft(),v.getTop(),v.getRight(),v.getBottom()};}
 private void capture(final ViewGroup parent,final View view,final int t,final int order){if(!enabled[t]||!view.isLaidOut()||pending.containsKey(view))return;cancelView(view);final int[] old=bounds(view);View.OnLayoutChangeListener listener=new View.OnLayoutChangeListener(){public void onLayoutChange(View v,int l,int top,int r,int b,int ol,int ot,int or,int ob){View.OnLayoutChangeListener self=pending.remove(v);if(self==null)return;v.removeOnLayoutChangeListener(self);final int[] target={l,top,r,b};if(Arrays.equals(old,target)||!ready(parent))return;final Run run=new Run();run.view=v;run.parent=parent;run.type=t;run.animator=ValueAnimator.ofFloat(0,1);run.finish=new Runnable(){public void run(){view.shirazSetAnimatedBounds(target[0],target[1],target[2],target[3]);}};run.animator.addUpdateListener(new ValueAnimator.AnimatorUpdateListener(){public void onAnimationUpdate(ValueAnimator a){float f=(Float)a.getAnimatedValue();int[] value=new int[4];for(int i=0;i<4;i++)value[i]=(int)Math.round(old[i]+((double)target[i]-old[i])*f);view.shirazSetAnimatedBounds(value[0],value[1],value[2],value[3]);}});view.shirazSetAnimatedBounds(old[0],old[1],old[2],old[3]);launch(run,Math.min(86400000,stagger[t]*order));}};pending.put(view,listener);view.addOnLayoutChangeListener(listener);}
 private void prepare(final ViewGroup parent,View excluded,int t){if(!enabled[t])return;int order=0;for(int i=0;i<parent.getChildCount();i++){View child=parent.getChildAt(i);if(child!=excluded&&child.getVisibility()==View.VISIBLE)capture(parent,child,t,order++);}if(parents){View ancestor=parent;for(int depth=0;ancestor!=null&&depth<128;depth++){capture(parent,ancestor,t,order++);ancestor=ancestor.getParent() instanceof View?(View)ancestor.getParent():null;}}
  if(cleanup==null&&!pending.isEmpty()){observer=parent.getViewTreeObserver();cleanup=new ViewTreeObserver.OnPreDrawListener(){public boolean onPreDraw(){clearPending();return true;}};observer.addOnPreDrawListener(cleanup);}
 }
 private void clearPending(){for(Map.Entry<View,View.OnLayoutChangeListener> entry:new ArrayList<Map.Entry<View,View.OnLayoutChangeListener>>(pending.entrySet()))entry.getKey().removeOnLayoutChangeListener(entry.getValue());pending.clear();if(cleanup!=null&&observer!=null&&observer.isAlive())observer.removeOnPreDrawListener(cleanup);cleanup=null;observer=null;}
 private void fade(final ViewGroup parent,final View view,boolean appearing,boolean visibility){int t=appearing?APPEARING:DISAPPEARING;if(!enabled[t])return;cancelView(view);final float alpha=view.getAlpha();final Run run=new Run();run.view=view;run.parent=parent;run.type=t;run.animator=ValueAnimator.ofFloat(appearing?0:alpha,appearing?alpha:0);if(!appearing){if(visibility)parent.shirazRetainVisibility(view);else parent.startViewTransition(view);}else view.setAlpha(0);run.finish=new Runnable(){public void run(){try{view.setAlpha(alpha);}finally{parent.endViewTransition(view);}}};run.animator.addUpdateListener(new ValueAnimator.AnimatorUpdateListener(){public void onAnimationUpdate(ValueAnimator a){view.setAlpha((Float)a.getAnimatedValue());}});launch(run,0);}
 public void addChild(ViewGroup parent,View child){if(!ready(parent))return;prepare(parent,child,CHANGE_APPEARING);fade(parent,child,true,false);}
 public void removeChild(ViewGroup parent,View child){if(!ready(parent))return;prepare(parent,child,CHANGE_DISAPPEARING);fade(parent,child,false,false);}
 public void showChild(ViewGroup parent,View child,int oldVisibility){addChild(parent,child);}public void hideChild(ViewGroup parent,View child,int newVisibility){if(!ready(parent))return;prepare(parent,child,CHANGE_DISAPPEARING);fade(parent,child,false,true);}
 public void showChild(ViewGroup parent,View child){showChild(parent,child,View.GONE);}public void hideChild(ViewGroup parent,View child){hideChild(parent,child,View.GONE);}
 public void layoutChange(ViewGroup parent){if(ready(parent)&&enabled[CHANGING])prepare(parent,null,CHANGING);}
 public void cancel(){if(canceling)return;canceling=true;Throwable failure=null;try{clearPending();for(Run run:new ArrayList<Run>(runs)){try{try{if(run.animator.isStarted())run.animator.cancel();}finally{finish(run);}}catch(RuntimeException|Error error){if(failure==null)failure=error;else if(failure!=error)failure.addSuppressed(error);}}}finally{canceling=false;}if(failure instanceof RuntimeException)throw (RuntimeException)failure;if(failure instanceof Error)throw (Error)failure;}
 public void cancel(int t){type(t);if(t==0||t==1||t==4)clearPending();for(Run run:new ArrayList<Run>(runs))if(run.type==t){try{if(run.animator.isStarted())run.animator.cancel();}finally{finish(run);}}}
}
